Local Ltac open_fctx CTX PURE :=
  lazymatch type of CTX with fi_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (FR & RJ & ITC & EAC & TC & WS & WT & ST & MU & WM & MI & SD);
  destruct PURE as (SP64 & TP64 & LO & CEIL & LEA & LR & LHI & LIT & ST_ & SS & STP & DT & DS & DTP & NZS & NZT & ITNZ & ITAL & EANZ & EAAL & TAL);
  pose proof (bytes_at_bound _ _ _ _ WS) as WSB; pose proof (bytes_at_bound _ _ _ _ WT) as WTB;
  pose proof (rw_cells_bound _ _ _ _ TC) as TCB; cbn [cells_size csize Nat.add length] in TCB, ST_, DT;
  pose proof (rw_cells_bound _ _ _ _ RJ) as RB; cbn [cells_size csize Nat.add length] in RB;
  pose proof (rw_cells_bound _ _ _ _ EAC) as EAB; cbn [cells_size csize Nat.add length TokItCells] in EAB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & _);
  hydeL ST_; hydeL SS; hydeL STP; hydeL DT; hydeL DS; hydeL DTP; hydeL ITAL; hydeL EAAL; hydeL TAL;
  unfold TokItCells, SZ_TOKIT, FINDIF_STACK, TOKIT_STACK, AINTRIN_STACK, AAPP_HI, fi_frame, tk_saved, shz in *; unfold wz in * end.

Local Ltac rebuild_fctx m sp R IT EA T SP TP :=
  try match goal with C : fi_ctx _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR : rw_cells _ mx (bv_unsigned sp + -208) (CB 8 ?j8 :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ ::
             [C8 ?x11; C8 ?x10; C8 ?x9; C8 ?x8; C8 ?x7; C8 ?x6; C8 ?x5; C8 ?x4; C8 ?x3; C8 ?x2; C8 ?x1; C8 ?x0; C8 ?xra]),
    RJ : rw_cells _ mx R [CB 40 ?junkR], ITC : rw_cells _ mx IT ?itc, EAC : rw_cells _ mx EA _,
    TC : rw_cells _ mx T (C8 _ :: C8 (Z_to_bv 64 (Z.of_nat (length ?tbs))) :: ?trest),
    WS : bytes_at _ mx SP ?sbs, WT : bytes_at _ mx TP _, ST : stk _ mx ?lo _,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx, SD : fi_side m _ _ _ _ _ _ _ _ |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : fi_ctx m mx sp (tk_saved x11 x10 x9 x8 x7 x6 x5 x4 x3 x2 x1 x0 xra) R IT EA T SP TP sbs tbs trest lo junkR j8 itc)
        by (unfold fi_ctx, fi_frame, tk_saved, shz, wz; repeat (split; [fast_eassumption|]); fast_eassumption)
  end end.

Lemma tok_suffix_off' : forall SP i sbs, 0 <= SP -> tok_suffix SP (SP + Z.of_nat i) sbs = skipn i (zbytes sbs).
Proof. intros SP i sbs HS. unfold tok_suffix. rewrite zbytes_skipn. f_equal. lia. Qed.

