(* [comment removed for export] *)
Lemma tokit_after_size : forall r a b, cells_size (tokit_cells_after r a b) = 40%nat.
Proof. intros [| |k l] a b; reflexivity. Qed.
Lemma tokit_after_wf : forall r a b, cells_wf (tokit_cells_after r a b).
Proof. intros [| |k l] a b; cbn; repeat split. Qed.
Lemma tokit_after_sized : forall m A r a b,
  rw_cells bsegs m A (tokit_cells_after r a b) -> rw_cells bsegs m A [CB 40 (cells_bytes (tokit_cells_after r a b))].
Proof.
  intros m A r a b C. rewrite <- (app_nil_r (tokit_cells_after r a b)) in C.
  apply (rw_cells_merge bsegs m A [] (tokit_cells_after r a b) []) in C. cbn [app] in C. rewrite tokit_after_size in C. exact C.
Qed.
